contract InvMutTest {
    C c;
    constructor() { c = new C(address(this), 0); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    // single public test function
    function run(uint256 sendAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000); require(address(this).balance >= (sendAmount)); require(sendAmount <= 1000000000000000000000000000000);
        // require the test contract has enough balance to send the wager
        require(address(this).balance >= sendAmount);
        // We only test the simple property: a successful wager registers the player and requires exact bet amount.
        bool wagerReverted;
        c.wager{value: sendAmount}(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
            wagerReverted = true;
        } else {
            wagerReverted = false;
        }

        bool isPlayer = c.hasPlayerWagered(address(this)); if (__ESBMC_reverted()) return;
        uint256 currentLimit = c.currentBetLimit(); if (__ESBMC_reverted()) return;

        // If wager succeeded then isPlayer must be true and currentLimit must equal the sent amount.
        assert((!wagerReverted) == (isPlayer && currentLimit == sendAmount));
    }

    receive() external payable {}
}

