pragma solidity ^0.8.0;

import {Test} from "forge-std/Test.sol";
import {PoCGame} from "../src/PoCGame.sol";

contract InvMutTest is Test {
    uint256 internal constant VALUE_CAP = 1000000000000000000000000000000;
    PoCGame c;

    function setUp() public {
        c = new PoCGame(address(this), 0);
    }

    function _run(uint256 sendAmount) internal {
        sendAmount = bound(sendAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(address(this).balance >= sendAmount);
        bool wagerReverted;
        try c.wager{value: sendAmount}() {
            wagerReverted = false;
        } catch {
            wagerReverted = true;
        }
        bool isPlayer;
        try c.hasPlayerWagered(address(this)) returns (bool __r) { isPlayer = __r; } catch { return; }
        uint256 currentLimit;
        try c.currentBetLimit() returns (uint256 __r) { currentLimit = __r; } catch { return; }
        assertTrue((!wagerReverted) == (isPlayer && currentLimit == sendAmount));
    }

    function testFuzz_run(uint256 sendAmount) public {
        _run(sendAmount);
    }

    receive() external payable {}
}
